// Deja el lote en la forma que espera el CRM y descarta lo que no procede.
// El watermark evita volver a llamar al CRM cuando no hay mensajes nuevos.
const state = $getWorkflowStaticData('global');
const lastSeenId = typeof state.lastPipelineMessageId === 'string'
  ? state.lastPipelineMessageId
  : null;

function isAfterWatermark(id) {
  if (lastSeenId === null) return true;
  try {
    return BigInt(id) > BigInt(lastSeenId);
  } catch {
    return false;
  }
}

const stats = { input: 0, invalid: 0, bots: 0, beforeWatermark: 0, empty: 0, accepted: 0 };
const mensajes = [];
for (const item of $input.all()) {
  stats.input += 1;
  const m = item.json;
  const messageId = String(m && (m.id ?? m.messageId) || '');
  const channelId = String(m && (m.channel_id ?? m.channelId) || '');
  if (!/^\d{17,20}$/.test(messageId) || !/^\d{17,20}$/.test(channelId)) {
    stats.invalid += 1;
    continue;
  }
  const author = m && typeof m.author === 'object' && m.author ? m.author : {};
  if (author.bot === true) {
    stats.bots += 1;
    continue;
  }
  if (!isAfterWatermark(messageId)) {
    stats.beforeWatermark += 1;
    continue;
  }
  const content = typeof m.content === 'string' ? m.content.trim() : '';
  if (content.length === 0) {
    stats.empty += 1;
    continue;
  }
  mensajes.push({
    messageId,
    channelId,
    authorId: author.id ? String(author.id) : undefined,
    authorUsername: author.username ? String(author.username) : undefined,
    content,
    timestamp: m.timestamp ? String(m.timestamp) : undefined,
  });
  stats.accepted += 1;
}

// Discord devuelve primero los más recientes. El CRM recibe orden cronológico.
mensajes.sort((a, b) => {
  const left = BigInt(a.messageId);
  const right = BigInt(b.messageId);
  return left < right ? -1 : left > right ? 1 : 0;
});
console.log('[pipeline-deals] filtro de lote', { ...stats, lastSeenId, newestAcceptedId: mensajes.at(-1)?.messageId ?? null });

// Sin mensajes posteriores al watermark no se llama al CRM.
if (mensajes.length === 0) return [];
return [{ json: { messages: mensajes.slice(0, 25) } }];

// Convierte solo resultados NUEVOS en una reacción sobre el mensaje original.
// 👀 = leído y pendiente de revisión; ⚠️ = guardado pero incompleto;
// ✅ = trato ya aprobado; 🚫 = rechazado; ❌ = fallo, se reintentará.
const channelId = String($('Config').first().json.channelId);
const lote = $('Preparar lote').first().json.messages;
const mensajes = Array.isArray(lote) ? lote : [];
const respuestaTieneOutcomes = Object.prototype.hasOwnProperty.call($json, 'outcomes');
let outcomes = Array.isArray($json.outcomes) ? $json.outcomes : [];

// El HTTP Request continúa por la salida normal después de agotar sus tres
// intentos. Si no llegó una respuesta válida del CRM, recuperamos los IDs del
// lote original y marcamos cada mensaje como fallo visible en Discord.
if (!respuestaTieneOutcomes) {
  outcomes = mensajes.map((mensaje) => ({
    messageId: mensaje.messageId,
    result: 'failed',
    status: null,
  }));
}

// El watermark solo avanza tras una respuesta completa y sin fallos. Así un
// error parcial se reintenta; los already_seen no vuelven a generar reacción.
const idsDevueltos = new Set(outcomes.map((outcome) => String(outcome && outcome.messageId || '')));
const respuestaCompleta = respuestaTieneOutcomes
  && outcomes.length === mensajes.length
  && mensajes.every((mensaje) => idsDevueltos.has(String(mensaje.messageId)));
const hayFallos = outcomes.some((outcome) => outcome && outcome.result === 'failed');
if (respuestaCompleta && !hayFallos && mensajes.length > 0) {
  const maxMessageId = mensajes.reduce((max, mensaje) => {
    const current = String(mensaje.messageId);
    return BigInt(current) > BigInt(max) ? current : max;
  }, String(mensajes[0].messageId));
  const state = $getWorkflowStaticData('global');
  state.lastPipelineMessageId = maxMessageId;
}

const emojiByStatus = {
  missing_info: '⚠️',
  pending_review: '👀',
  created: '✅',
  rejected: '🚫',
};

return outcomes.flatMap((outcome) => {
  if (!outcome || ['ignored', 'already_seen'].includes(outcome.result) || !outcome.messageId) return [];
  const emoji = outcome.result === 'failed'
    ? '❌'
    : (emojiByStatus[outcome.status] || '👀');
  return [{
    json: {
      messageId: String(outcome.messageId),
      channelId,
      emoji,
      result: outcome.result,
      status: outcome.status || null,
      draftId: outcome.draftId || null,
    },
  }];
});
